{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Overly permissive primitive IAM role",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "HIGH",
      "explanation": "The project-wide roles/editor primitive role grants both users broad permissions to create, modify, and delete most Google Cloud resources. This violates least privilege and increases the impact of a compromised user account."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/browser\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}\n",
  "fix_summary": "Replaced the broad primitive Editor role with the predefined Browser role, which permits project resource discovery without granting resource modification privileges."
}
